let mySize;

// a shader variable
let theShader;
let shaderTexture;

let theta = 0;

function preload() {
	theShader = createShader(vert, frag)
}

function setup() {
	noCursor();
	// mySize = max(windowWidth, windowHeight);
	mySize = 600;
	// shaders require WEBGL mode to work
	createCanvas(mySize, mySize, WEBGL);
	noStroke();
	shaderTexture = createGraphics(width, height, WEBGL);
	shaderTexture.noStroke();
	background("#202020");
}

function draw() {  
  // shader() sets the active shader with our shader
  shader(theShader);

  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_frame", frameCount/100.0);
  theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/1000.0, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)/1000.0]);

  // rect gives us some geometry on the screen
  rect(0,0,width, height);
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function keyPressed() {
	//noLoop();
	saveCanvas("Shaders_007_2022", "png");
}

// === Tab: frag ===
//noprotect
const frag = `
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_frame;
uniform vec2 u_mouse;

#define SMOOTH(r, R)(1.0 - smoothstep(R - 1.0, R + 1.0, r))
#define RANGE(a, b, x)(step(a, x) * (1.0 - step(b, x)))
#define RS(a, b, x)(smoothstep(a - 1.0, a + 1.0, x) * (1.0 - smoothstep(b - 1.0, b + 1.0, x)))
#define M_PI 3.1415926535897932384626433832795

#define blue1 vec3(0.74, 0.95, 1.00)
#define blue2 vec3(0.87, 0.98, 1.00)
#define blue3 vec3(0.35, 0.76, 0.83)
#define blue4 vec3(0.953, 0.969, 0.89)
#define red vec3(1.00, 0.38, 0.227)

#define MOV(a, b, c, d, t)(vec2(a * cos(t) + b * cos(0.5 * (t)), c * sin(t) + d * cos(0.5 * (t))))

float circle(vec2 uv, vec2 center, float radius, float width) {
	float r = length(uv - center);
	return SMOOTH(r - width / 2.0, radius) - SMOOTH(r + width / 2.0, radius);
}

float circle2(vec2 uv, vec2 center, float radius, float width, float opening) {
	vec2 d = uv - center;
	float r = sqrt(dot(d, d));
	d = normalize(d);
	if (abs(d.y) > opening)
		return SMOOTH(r - width / 2.0, radius) - SMOOTH(r + width / 2.0, radius);
	else
		return 0.0;
}

float circle3(vec2 uv, vec2 center, float radius, float width) {
	vec2 d = uv - center;
	float r = sqrt(dot(d, d));
	d = normalize(d);
	float theta = 50.0 * (atan(d.y, d.x) / M_PI);
	return smoothstep(1.0, 2.1, abs(mod(theta + 2.0, 45.0) - 2.0)) *
		mix(0.5, 2.0, step(2.0, abs(mod(theta, 4.0) - 25.0))) *
		(SMOOTH(r - width / 2.0, radius) - SMOOTH(r + width / 2.0, radius));
}

float bip1(vec2 uv, vec2 center) {
	return SMOOTH(length(uv - center), 75.0);
}

float bip2(vec2 uv, vec2 center) {
	float r = length(uv - center);
	float R = 4.0 + mod(87.0 * u_frame, 200.0);
	return (0.5 - 0.5 * cos(30.0 * u_frame)) * SMOOTH(r, 5.0) +
		SMOOTH(2.0, r) - SMOOTH(2.0, r) +
		smoothstep(max(8.0, R - 20.0), R, r) - SMOOTH(R, r);
}

void main() {
	vec3 finalColor = vec3(0.0);
	vec2 uv = gl_FragCoord.xy;
	//center of the image
	vec2 c = u_resolution.xy / 1.0;
	for (int i = 0; i < 50; i++) {
		//finalColor += circle(uv, c, 100.0 + 50.0 * float(i), 0.5 * float(i)) * red;
		//finalColor += circle3(uv, c, 50.0*float(i)+125.0, 0.15*float(i)) * blue3;
		finalColor += 3.7 * circle2(uv, c, 5.0 * float(i) + 125.0, 1.0, 0.5 + 1.2 * fract(u_frame/2.0 * ceil(float(i)))) * blue1;
		finalColor += 1.7 * circle2(uv, c, 7.5 * float(i) + 125.0, 1.0, 0.5 + 1.2 * fract(u_frame/2.0 * ceil(float(i)))) * blue1;
	}




	//animate some bips with random movements
	vec2 p = 0.1 * MOV(15.3, 10.0, 10.0, 10.4, 30.0 + 100.1 * u_frame);
	finalColor += bip1(uv, c + p) * vec3(1.5, 0.75, 1) * red;
	// p = 120.0 * MOV(0.9, -1.1, 1.7, 0.8, -2.0 + sin(1.1 * u_frame) + 0.15 * u_frame);
	// finalColor += bip1(uv, c + p) * vec3(1.75, 0.5, 1) * blue3;
	// p = 50.0 * MOV(1.54, 1.7, 1.37, 1.8, 3.0 + 2.2 * u_frame);
	// finalColor += bip1(uv, c + p) * vec3(1.1, 0.5, 1) * blue1;


	gl_FragColor = vec4(finalColor, 1.0);
}
// `

// === Tab: vert ===
const vert = `
// vert file and comments from adam ferriss
// https://github.com/aferriss/p5jsShaderExamples

// our vertex data
attribute vec3 aPosition;

// our texcoordinates
attribute vec2 aTexCoord;

void main() {

  // copy the position data into a vec4, using 1.0 as the w component
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  // send the vertex information on to the fragment shader
  gl_Position = positionVec4;
}
`;

